    /**
     * Tests getting all Chargebacks.
     *
     * @return    Collection
     */
    public List<Chargeback> testGetAll() throws Throwable {
    LOGGER.info( "ChargebackTest:testGetAll() - Retrieving Collection of Chargebacks:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Chargeback : " );
    List<Chargeback> collection  = null;

    try {
        // call the static get method on the ChargebackService
        collection = service.getAllChargeback();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Chargeback currEntity  = null;
            Iterator<Chargeback> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getChargebackId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

